CREATE VIEW "public"."pipeline_funnel" AS (SELECT c.niche, count(*) AS in_play, count(*) FILTER (WHERE c.domain IS NOT NULL) AS with_domain, count(*) FILTER (WHERE EXISTS (SELECT 1 FROM documents d WHERE d.company_id = c.id)) AS crawled, count(*) FILTER (WHERE EXISTS (SELECT 1 FROM people p WHERE p.company_id = c.id)) AS named_person, count(*) FILTER (WHERE EXISTS (SELECT 1 FROM leads l WHERE l.company_id = c.id AND l.status::text = 'verified'::text AND l.first_name IS NOT NULL)) AS verified_named_lead FROM companies c WHERE c.decline_reason IS NULL GROUP BY c.niche);--> statement-breakpoint
CREATE VIEW "public"."pipeline_leaks" AS (WITH firms AS ( SELECT c.id, c.niche, EXISTS ( SELECT 1 FROM people p WHERE p.company_id = c.id) AS has_person, EXISTS ( SELECT 1 FROM leads l WHERE l.company_id = c.id AND l.first_name IS NOT NULL) AS has_named_lead, EXISTS ( SELECT 1 FROM documents d WHERE d.company_id = c.id AND NOT d.is_shell) AS crawled, EXISTS ( SELECT 1 FROM contact_candidates cc JOIN people p ON p.id = cc.person_id WHERE p.company_id = c.id AND cc.state::text = 'queued'::text) AS queued FROM companies c WHERE c.decline_reason IS NULL ), latest AS ( SELECT DISTINCT ON (v.lead_id) v.lead_id, v.result FROM verifications v WHERE v.lead_id IS NOT NULL ORDER BY v.lead_id, v.checked_at DESC ), named AS ( SELECT f.niche, lt.result FROM leads l JOIN firms f ON f.id = l.company_id JOIN latest lt ON lt.lead_id = l.id WHERE l.first_name IS NOT NULL ) SELECT f.niche, ( SELECT count(*) FROM named n WHERE n.niche::text = f.niche::text AND n.result::text = 'catch_all'::text) AS catch_all_leads, ( SELECT count(*) FROM named n WHERE n.niche::text = f.niche::text AND n.result::text = 'risky'::text) AS risky_leads, count(*) FILTER (WHERE f.queued AND NOT f.has_named_lead) AS queued_firms, count(*) FILTER (WHERE f.crawled AND NOT f.has_person) AS crawled_no_person_firms FROM firms f GROUP BY f.niche);